// Procesar input y añadir metadata
const items = $input.all();

for (const item of items) {
  // Determinar fuente
  const source = item.json.chat_id ? 'telegram' : 'gmail';

  // Extraer texto según tipo
  let extractedText = '';
  let originalFiles = [];

  if (item.json.text) {
    // Texto directo
    extractedText = item.json.text;
  } else if (item.json.transcription) {
    // Audio transcrito
    extractedText = item.json.transcription;
  } else if (item.json.extracted_text) {
    // Documento procesado
    extractedText = item.json.extracted_text;
  } else if (item.json.subject && item.json.textPlain) {
    // Email de Gmail
    extractedText = `Asunto: ${item.json.subject}\n\n${item.json.textPlain}`;
    if (item.json.attachments) {
      originalFiles = item.json.attachments.map(att => att.filename);
    }
  }

  // Añadir metadata
  item.json.processed_data = {
    source: source,
    source_message_id: item.json.message_id || item.json.id,
    original_text: extractedText,
    original_files: originalFiles,
    processed_at: new Date().toISOString(),
    content_type: item.json.voice || item.json.audio ? 'audio' : 
                  item.json.document || item.json.attachments ? 'document' : 'text'
  };
}

return items;

// Leer configuración LLM y preparar request
const fs = require('fs');
const path = require('path');

// Leer configuración LLM
const configPath = path.join(__dirname, '../config/llm-config.json');
const llmConfig = JSON.parse(fs.readFileSync(configPath, 'utf8'));
const activeProvider = llmConfig.providers[llmConfig.active_provider];

// Leer prompt de extracción
const promptPath = path.join(__dirname, '../prompts/extractor-prompt.txt');
const extractorPrompt = fs.readFileSync(promptPath, 'utf8');

// Preparar datos para el request
const items = $input.all();

for (const item of items) {
  const briefText = item.json.processed_data.original_text;

  // Configurar request según provider activo
  if (llmConfig.active_provider === 'gemini') {
    item.json.llm_request = {
      url: activeProvider.api_endpoint,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: {
        contents: [{
          parts: [{
            text: `${extractorPrompt}\n\nBrief a analizar:\n${briefText}`
          }]
        }],
        generationConfig: {
          temperature: activeProvider.temperature,
          maxOutputTokens: activeProvider.max_tokens,
          responseMimeType: "application/json"
        }
      },
      auth: {
        type: 'query',
        key: 'key',
        value: process.env[activeProvider.api_key_env]
      }
    };
  } else if (llmConfig.active_provider === 'openai') {
    item.json.llm_request = {
      url: activeProvider.api_endpoint,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${process.env[activeProvider.api_key_env]}`
      },
      body: {
        model: activeProvider.model,
        messages: [{
          role: 'system',
          content: extractorPrompt
        }, {
          role: 'user',
          content: `Brief a analizar:\n${briefText}`
        }],
        temperature: activeProvider.temperature,
        max_tokens: activeProvider.max_tokens,
        response_format: activeProvider.response_format
      }
    };
  }

  item.json.llm_provider = llmConfig.active_provider;
}

return items;

// Procesar respuesta LLM y extraer JSON
const items = $input.all();

for (const item of items) {
  let extractedData;

  try {
    if (item.json.llm_provider === 'gemini') {
      const response = item.json.candidates[0].content.parts[0].text;
      extractedData = JSON.parse(response);
    } else if (item.json.llm_provider === 'openai') {
      const response = item.json.choices[0].message.content;
      extractedData = JSON.parse(response);
    }

    // Validar que tiene estructura básica requerida
    if (!extractedData.cliente || !extractedData.proyecto) {
      throw new Error('Estructura de brief inválida');
    }

    item.json.extracted_brief = extractedData;
    item.json.extraction_success = true;
    item.json.extraction_timestamp = new Date().toISOString();

  } catch (error) {
    item.json.extraction_success = false;
    item.json.extraction_error = error.message;
    item.json.raw_response = item.json;
  }
}

return items;

// Preparar validación QA
const fs = require('fs');
const path = require('path');

// Leer configuración LLM
const configPath = path.join(__dirname, '../config/llm-config.json');
const llmConfig = JSON.parse(fs.readFileSync(configPath, 'utf8'));
const activeProvider = llmConfig.providers[llmConfig.active_provider];

// Leer prompt de validación
const promptPath = path.join(__dirname, '../prompts/validator-prompt.txt');
const validatorPrompt = fs.readFileSync(promptPath, 'utf8');

const items = $input.all();

for (const item of items) {
  const extractedBrief = JSON.stringify(item.json.extracted_brief, null, 2);

  // Configurar request de validación
  if (llmConfig.active_provider === 'gemini') {
    item.json.qa_request = {
      url: activeProvider.api_endpoint,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: {
        contents: [{
          parts: [{
            text: `${validatorPrompt}\n\nBrief extraído para validar:\n${extractedBrief}`
          }]
        }],
        generationConfig: {
          temperature: activeProvider.temperature,
          maxOutputTokens: activeProvider.max_tokens,
          responseMimeType: "application/json"
        }
      },
      auth: {
        type: 'query',
        key: 'key',
        value: process.env[activeProvider.api_key_env]
      }
    };
  } else if (llmConfig.active_provider === 'openai') {
    item.json.qa_request = {
      url: activeProvider.api_endpoint,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${process.env[activeProvider.api_key_env]}`
      },
      body: {
        model: activeProvider.model,
        messages: [{
          role: 'system',
          content: validatorPrompt
        }, {
          role: 'user',
          content: `Brief extraído para validar:\n${extractedBrief}`
        }],
        temperature: activeProvider.temperature,
        max_tokens: activeProvider.max_tokens,
        response_format: activeProvider.response_format
      }
    };
  }
}

return items;

// Procesar resultado de validación QA
const items = $input.all();

for (const item of items) {
  let validationResult;

  try {
    if (item.json.llm_provider === 'gemini') {
      const response = item.json.candidates[0].content.parts[0].text;
      validationResult = JSON.parse(response);
    } else if (item.json.llm_provider === 'openai') {
      const response = item.json.choices[0].message.content;
      validationResult = JSON.parse(response);
    }

    item.json.validation_result = validationResult;
    item.json.validation_timestamp = new Date().toISOString();

  } catch (error) {
    item.json.validation_result = {
      validation_passed: false,
      confidence_score: 0,
      blockers: [`Error procesando validación: ${error.message}`]
    };
  }
}

return items;

// Actualizar Supabase con URL de presentación
const items = $input.all();

for (const item of items) {
  const presentationUrl = `https://docs.google.com/presentation/d/${item.json.presentationId}/edit`;

  item.json.update_request = {
    url: `${process.env.SUPABASE_URL}/rest/v1/briefs?id=eq.${item.json.brief_id}`,
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${process.env.SUPABASE_ANON_KEY}`,
      'apikey': process.env.SUPABASE_ANON_KEY,
      'Content-Type': 'application/json'
    },
    body: {
      presentation_url: presentationUrl,
      presentation_id: item.json.presentationId
    }
  };

  item.json.presentation_url = presentationUrl;
}

return items;

// Generar token de seguridad y preparar notificación de aprobación
const { v4: uuidv4 } = require('uuid');
const items = $input.all();

for (const item of items) {
  // Generar token de seguridad único
  const securityToken = uuidv4().replace(/-/g, '');

  // Preparar datos para template
  const templateData = {
    brief_id: item.json.brief_id,
    security_token: securityToken,
    cliente: item.json.extracted_brief.cliente,
    proyecto: item.json.extracted_brief.proyecto,
    audiencia: item.json.extracted_brief.audiencia,
    servicios_requeridos: item.json.extracted_brief.servicios_requeridos,
    timeline: item.json.extracted_brief.timeline,
    presupuesto: item.json.extracted_brief.presupuesto,
    validation: item.json.validation_result,
    presentation_url: item.json.presentation_url,
    webhook_url: process.env.N8N_WEBHOOK_URL,
    current_date: new Date().toLocaleDateString('es-ES'),
    metadata: {
      urgencia: item.json.extracted_brief.metadata?.urgencia || 'media',
      urgencia_alta: (item.json.extracted_brief.metadata?.urgencia === 'alta')
    }
  };

  // Guardar token en Supabase para validación posterior
  item.json.approval_token_request = {
    url: `${process.env.SUPABASE_URL}/rest/v1/brief_aprobaciones`,
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${process.env.SUPABASE_ANON_KEY}`,
      'apikey': process.env.SUPABASE_ANON_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: {
      brief_id: item.json.brief_id,
      security_token: securityToken,
      decision: 'pendiente',
      webhook_source: 'email'
    }
  };

  item.json.template_data = templateData;
  item.json.security_token = securityToken;
}

return items;

// Identificar equipos asignados y preparar notificaciones
const items = $input.all();

for (const item of items) {
  const servicios = item.json.extracted_brief.servicios_requeridos;
  const equiposAsignados = [];
  const notificaciones = [];

  // Mapear servicios a equipos
  const equipoMapping = {
    'equipo_creativo': {
      name: 'Equipo Creativo',
      role: 'Creatividad y Estrategia',
      emails: process.env.CREATIVE_TEAM_EMAILS?.split(',') || ['creativo@zelva.com'],
      slack_id: process.env.CREATIVE_TEAM_SLACK_ID || 'creativo-team',
      channel: '#equipo-creativo',
      services: ['estrategia_digital', 'branding_diseno', 'contenido_copywriting'],
      responsibilities: [
        'Desarrollar estrategia creativa',
        'Crear conceptos y mensajes clave',
        'Diseñar identidad visual del proyecto',
        'Supervisar consistencia de marca'
      ],
      deliverables: [
        'Estrategia creativa',
        'Brief creativo',
        'Conceptos visuales',
        'Guidelines de comunicación'
      ],
      skills_needed: ['estrategia', 'creatividad', 'branding']
    },
    'equipo_medios': {
      name: 'Equipo de Medios',
      role: 'Publicidad Pagada y Performance',
      emails: process.env.MEDIA_TEAM_EMAILS?.split(',') || ['medios@zelva.com'],
      slack_id: process.env.MEDIA_TEAM_SLACK_ID || 'medios-team',
      channel: '#equipo-medios',
      services: ['publicidad_pagada', 'seo_sem', 'social_media'],
      responsibilities: [
        'Planificar y ejecutar campañas pagadas',
        'Optimizar performance y métricas',
        'Gestionar presupuestos de medios',
        'Reportar resultados y ROI'
      ],
      deliverables: [
        'Plan de medios',
        'Configuración de campañas',
        'Reportes de performance',
        'Optimizaciones semanales'
      ],
      skills_needed: ['paid_media', 'analitica', 'seo_sem']
    },
    'equipo_diseno': {
      name: 'Equipo de Diseño',
      role: 'Diseño Gráfico y Desarrollo',
      emails: process.env.DESIGN_TEAM_EMAILS?.split(',') || ['diseno@zelva.com'],
      slack_id: process.env.DESIGN_TEAM_SLACK_ID || 'diseno-team',
      channel: '#equipo-diseno',
      services: ['desarrollo_web', 'branding_diseno'],
      responsibilities: [
        'Diseñar piezas gráficas y digitales',
        'Desarrollar landing pages y sitios web',
        'Crear assets para campañas',
        'Mantener consistencia visual'
      ],
      deliverables: [
        'Diseños para campañas',
        'Landing pages',
        'Assets digitales',
        'Mockups y prototipos'
      ],
      skills_needed: ['desarrollo_web', 'creatividad', 'diseno']
    },
    'account_management': {
      name: 'Account Management',
      role: 'Gestión de Cuenta y Relación Cliente',
      emails: process.env.ACCOUNT_TEAM_EMAILS?.split(',') || ['cuentas@zelva.com'],
      slack_id: process.env.ACCOUNT_TEAM_SLACK_ID || 'account-team',
      channel: '#account-management',
      services: ['all'], // Siempre asignado
      responsibilities: [
        'Gestionar relación con cliente',
        'Coordinar entregas y timelines',
        'Comunicar avances y resultados',
        'Asegurar satisfacción del cliente'
      ],
      deliverables: [
        'Reportes de estado',
        'Comunicación con cliente',
        'Coordinación de equipos',
        'Presentaciones ejecutivas'
      ],
      skills_needed: ['account_management', 'project_management']
    }
  };

  // Determinar qué equipos asignar
  Object.entries(equipoMapping).forEach(([equipoId, equipoInfo]) => {
    let shouldAssign = false;

    if (equipoInfo.services.includes('all')) {
      shouldAssign = true;
    } else {
      shouldAssign = equipoInfo.services.some(service => servicios[service] === true);
    }

    if (shouldAssign) {
      equiposAsignados.push(equipoId);

      // Crear notificación para cada email del equipo
      equipoInfo.emails.forEach(email => {
        notificaciones.push({
          type: 'email',
          team_id: equipoId,
          team_name: equipoInfo.name,
          team_role: equipoInfo.role,
          email: email,
          channel: equipoInfo.channel,
          slack_id: equipoInfo.slack_id,
          responsibilities: equipoInfo.responsibilities,
          deliverables: equipoInfo.deliverables,
          skills_needed: equipoInfo.skills_needed
        });
      });

      // Crear notificación Slack para el equipo
      notificaciones.push({
        type: 'slack',
        team_id: equipoId,
        team_name: equipoInfo.name,
        team_role: equipoInfo.role,
        channel: equipoInfo.channel,
        slack_id: equipoInfo.slack_id,
        responsibilities: equipoInfo.responsibilities,
        deliverables: equipoInfo.deliverables,
        skills_needed: equipoInfo.skills_needed
      });
    }
  });

  // Calcular estimaciones específicas por equipo
  const totalWeeks = item.json.validation_result?.estimated_resources?.duration_weeks || 8;
  const estimatedHours = Math.round(totalWeeks * 10); // 10h por semana promedio

  // Preparar datos para templates
  item.json.team_notifications = notificaciones.map(notif => ({
    ...notif,
    ...item.json.template_data, // Incluir todos los datos del brief
    team: {
      estimated_hours: estimatedHours,
      duration_weeks: totalWeeks
    },
    timeline: {
      ...item.json.extracted_brief.timeline,
      duration_weeks: totalWeeks,
      team_milestones: [
        {
          fecha: item.json.extracted_brief.timeline?.fecha_inicio_preferida,
          descripcion: 'Kick-off del proyecto'
        },
        {
          fecha: new Date(Date.now() + (totalWeeks * 7 * 24 * 60 * 60 * 1000 / 2)).toISOString().split('T')[0],
          descripcion: 'Primera revisión y entregables intermedios'
        },
        {
          fecha: item.json.extracted_brief.timeline?.fecha_entrega_final,
          descripcion: 'Entrega final del proyecto'
        }
      ]
    },
    account_manager: {
      name: process.env.DEFAULT_ACCOUNT_MANAGER_NAME || 'Account Manager',
      email: process.env.DEFAULT_ACCOUNT_MANAGER_EMAIL || 'cuentas@zelva.com',
      slack_id: process.env.DEFAULT_ACCOUNT_MANAGER_SLACK_ID || 'account-manager'
    },
    project_manager: {
      name: process.env.DEFAULT_PROJECT_MANAGER_NAME || 'Project Manager',
      email: process.env.DEFAULT_PROJECT_MANAGER_EMAIL || 'proyectos@zelva.com',
      slack_id: process.env.DEFAULT_PROJECT_MANAGER_SLACK_ID || 'project-manager'
    },
    next_steps: [
      'Revisar el brief completo y la presentación',
      'Programar kick-off meeting con el equipo',
      'Acceder al proyecto en COR y familiarizarse',
      'Contactar con el PM si hay dudas o necesidades específicas'
    ],
    cor_project_url: item.json.cor_project_url || `${process.env.COR_BASE_URL}/projects/${item.json.project_id}`,
    calendar_scheduling_url: process.env.CALENDAR_SCHEDULING_URL || 'https://calendar.zelva.com',
    slack_channel_url: `${process.env.SLACK_WORKSPACE_URL}/channels/proyecto-${item.json.brief_id}`,
    urgent_contact_needed: (item.json.extracted_brief.metadata?.urgencia === 'alta')
  }));

  item.json.equipos_asignados = equiposAsignados;
}

return items;
